let rows=[];let rng="Sheet1";while(rng){const r=await tools.read_range({range:rng});rows.push(...r.values);rng=r.truncated?r.next_range:null;}
const months=new Set(rows.slice(1).map(r=>r[1]));const regions=new Set(rows.slice(1).map(r=>JSON.stringify(r[0])));
const odd=rows.slice(1).filter(r=>typeof r[3]!=="number"||typeof r[4]!=="number");
return {n:rows.length,months:[...months],regions:[...regions],odd, tail:rows.slice(-5)};

let rows=[];let rg="Sheet1!A1:E243";while(rg){const r=await tools.read_range({range:rg});rows.push(...r.values);rg=r.next_range;}
const regions={};const odd=[];
rows.slice(1).forEach((v,i)=>{const [reg,m,p,u,pr]=v;regions[JSON.stringify(reg)]=(regions[JSON.stringify(reg)]||0)+1;if(typeof u!=="number"||typeof pr!=="number")odd.push([i+2,v]);});
return {n:rows.length,regions,odd,last:rows.slice(-3)};

let rows=[];let rg="Sheet1!A1:E241";while(rg){const r=await tools.read_range({range:rg});rows.push(...r.values);rg=r.next_range;}
const t={};rows.slice(1).forEach(([reg,,,u,p])=>t[reg]=(t[reg]||0)+u*p);
const s=Object.entries(t).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[k,String(Math.round(v*100)/100)]);
await tools.add_sheet({name:"Summary"});
const w=await tools.set_values({range:"Summary!A1",values:[["Region","Revenue"],...s]});
const chk=await tools.read_range({range:"Summary"});return {s,chk:chk.values};

await tools.set_values({range:"Sheet1!F1",values:[["Band"]]});const r=await tools.set_values({range:"Sheet1!F2:F241",values:[["=IF(D2*E2>1000,\"High\",\"Normal\")"]]});
let out=[],rng="Sheet1!F2:F241";while(rng){const x=await tools.read_range({range:rng});out.push(...x.values.map(v=>v[0]));rng=x.next_range;}
const c={};out.forEach(v=>c[v]=(c[v]||0)+1);return c;

const info = await tools.get_canvas_info();
const px = await tools.get_region_pixels({});
return {info, sample: JSON.stringify(px).slice(0,500)};

