const r = await tools.get_region_pixels({x:0,y:0,width:64,height:64,source:"layer",layer:"L1"});
const rows = r.rows;
const legend = r.legend;
const out = rows.map(row => row.slice(0,32).split('').reverse().map(c=>c==='.'?'~':c).join(''));
for (let y=0;y<64;y+=16){
  await tools.paint_rows({x:32,y,rows:out.slice(y,y+16),legend,layer:"L1"});
}
const c = await tools.get_region_pixels({x:0,y:0,width:64,height:64,source:"layer",layer:"L1"});
const bad = c.rows.filter(row=>row!==row.split('').reverse().join('')).length;
return {legend, bad, sample: c.rows.slice(0,3)};

