const legend=r.legend;
const out=rows.map(s=>{const l=s.slice(0,32);return [...l].reverse().map(c=>c=='.'?'~':c).join('')});
for(let y=0;y<64;y+=16){await tools.paint_rows({x:32,y,rows:out.slice(y,y+16),legend,layer:"L1"});}
const c=await tools.get_region_pixels({x:0,y:0,width:64,height:64,source:"layer",layer:"L1"});
let bad=0;c.rows.forEach(s=>{for(let x=0;x<32;x++)if(s[x]!=s[63-x])bad++});
return {legend,bad,sample:c.rows.slice(0,3)};

