const r = await tools.get_region_pixels({x:0,y:0,width:32,height:64,source:"layer",layer:"L1"});
const rows = r.rows;
const legend = r.legend;
const out = rows.map(row => row.split('').reverse().join('').replace(/\./g,'~'));
for (let y=0;y<64;y+=16){
  await tools.paint_rows({x:32,y,rows:out.slice(y,y+16),legend, layer:"L1"});
}
const full = await tools.get_region_pixels({x:0,y:0,width:64,height:64,source:"layer",layer:"L1"});
let bad=0; full.rows.forEach(row=>{for(let i=0;i<32;i++) if(row[i]!==row[63-i]) bad++;});
const left = await tools.get_region_pixels({x:0,y:0,width:32,height:64,source:"layer",layer:"L1"});
return {legend, bad, leftSame: JSON.stringify(left.rows)===JSON.stringify(rows), keys:Object.keys(r)};

